COMMENT ON TABLE CMRC.LOCAL_MATERIAL_BILL_DTL IS 'Penalty => " Sample Store(06,18,20) Billing "';

COMMENT ON COLUMN CMRC.LOCAL_MATERIAL_BILL_DTL.MRN_NO IS 'MRN_NO => RAW MATERIALS AND PACKAGING ITEMS  BILLING 
ALSO USING  
MRN_NO AS GRN_NO =>SAMPLE STORE(PROMOTIONAL ITEMS) BILLING';

COMMENT ON COLUMN CMRC.LOCAL_MATERIAL_BILL_DTL.QC_REF_NO IS 'QC_REF_NO=> RAW MATERIALS AND PACKAGING ITEMS  BILLING  
ALSO USING   
QCN_NO AS QCN_NO =>SAMPLE STORE(PROMOTIONAL ITEMS) BILLING';

COMMENT ON COLUMN CMRC.LOCAL_MATERIAL_BILL_DTL.PENALTY IS 'Penalty => " Sample Store(06,18,20) Billing "';


