CREATE OR REPLACE TRIGGER CMRC.REQ_ITEM_TR
AFTER DELETE ON CMRC.REQ_ITEM FOR EACH ROW
BEGIN                             
       INSERT INTO REQ_ITEM_HIST (REQ_NO, ITEM_CODE, QNTY, UOM, REMARKS, SPECI_CODE,REQ_DT,EDIT_BY, EDIT_DT, APRV_BY, APRV_DT, APRV_QNTY, QUAT_NO, IND_NO, CNCL_FLAG, DEPT_APRV_ID, DEPT_APRV_DATE, MITEM_CODE, CNCL_REASON, IS_DEPT_APRV,CNCL_BY, CNCL_DT, ASSIGN_EMP_CODE, ASSIGN_DT)
       VALUES
       (:OLD.REQ_NO, :OLD.ITEM_CODE, :OLD.QNTY, :OLD.UOM, :OLD.REMARKS, :OLD.SPECI_CODE,:OLD.REQ_DT,:OLD.EDIT_BY, :OLD.EDIT_DT, :OLD.APRV_BY, :OLD.APRV_DT, :OLD.APRV_QNTY, :OLD.QUAT_NO, :OLD.IND_NO, :OLD.CNCL_FLAG, :OLD.DEPT_APRV_ID, :OLD.DEPT_APRV_DATE,:OLD.MITEM_CODE, :OLD.CNCL_REASON, :OLD.IS_DEPT_APRV,:OLD.CNCL_BY, :OLD.CNCL_DT, :OLD.ASSIGN_EMP_CODE, :OLD.ASSIGN_DT);
END;
/


CREATE OR REPLACE TRIGGER CMRC.HO_STA_ITEM_TR
AFTER UPDATE ON CMRC.HO_STA_ITEM FOR EACH ROW
BEGIN
       INSERT INTO HO_STA_ITEM_HIST(ITEM_CODE, OLD_ITEM_DESC, NEW_ITEM_DESC, OLD_UOM, NEW_UOM, ENTER_DT, ITEM_GROUP_CODE,USER_ID)
